// Command configschema exports the configuration schema of the server (wire.ConfigSchema) to
// architecture/config-schema.json, so that the documentation gate can compare the schema with the
// chapter tables without a Go toolchain (ruling L4; docs/operations/configuration.md section 4,
// generated by tools/configdoc/configdoc.py).
//
// The file is JSON with a two-space indent and a final newline:
//
//	{"version": 1, "keys": [{"name", "env", "kind", "default", "required", "enum", "min", "max",
//	                         "chapter", "doc"}]}
//
// Keys are sorted by name and every field is always present: enum as a list (empty for other
// kinds), required as a bool, all others as strings ("" when unset). env is config.EnvName of the
// name, kind is config.Kind.String. Run it from services/server through go generate, which
// make codegen-check runs and compares:
//
//	go generate ./tools/configschema
//
// or directly, with the flag default shown:
//
//	go run ./tools/configschema -out architecture/config-schema.json
//
// Exit codes: 0 written, 1 invalid schema or I/O error, 2 usage error.
package main

//go:generate go run . -out ../../architecture/config-schema.json

import (
	"bytes"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/OWNER/bothy/services/server/internal/platform/config"
	"github.com/OWNER/bothy/services/server/internal/wire"
)

// fileVersion is the format version of the exported file; tools/configdoc rejects any other.
const fileVersion = 1

// Exit codes of run.
const (
	exitOK      = 0
	exitFailure = 1
	exitUsage   = 2
)

// schemaFile is the exported document.
type schemaFile struct {
	Version int       `json:"version"`
	Keys    []fileKey `json:"keys"`
}

// fileKey is one key in the exported document. The field order is the order in the file.
type fileKey struct {
	Name     string   `json:"name"`
	Env      string   `json:"env"`
	Kind     string   `json:"kind"`
	Default  string   `json:"default"`
	Required bool     `json:"required"`
	Enum     []string `json:"enum"`
	Min      string   `json:"min"`
	Max      string   `json:"max"`
	Chapter  string   `json:"chapter"`
	Doc      string   `json:"doc"`
}

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

// defaultOut is the output path relative to services/server, where go generate runs this
// command from the package directory with an explicit -out instead.
const defaultOut = "architecture/config-schema.json"

// run is main without the process: it parses args, exports the schema of the server and returns
// the exit code. Errors go to stderr; -h prints the usage to stdout.
func run(args []string, stdout, stderr io.Writer) int {
	return runWith(args, stdout, stderr, wire.ConfigSchema)
}

// runWith is run with the schema constructor as a parameter, so tests can pass an invalid one.
func runWith(args []string, stdout, stderr io.Writer, schema func() (*config.Schema, error)) int {
	out, help, err := parseArgs(args)
	switch {
	case help:
		writeUsage(stdout)
		return exitOK
	case err != nil:
		_, _ = fmt.Fprintf(stderr, "configschema: %v\n", err)
		writeUsage(stderr)
		return exitUsage
	}
	s, err := schema()
	if err != nil {
		_, _ = fmt.Fprintf(stderr, "configschema: %v\n", err)
		return exitFailure
	}
	data, err := export(s.Keys())
	if err == nil {
		err = writeFile(out, data)
	}
	if err != nil {
		_, _ = fmt.Fprintf(stderr, "configschema: write %s: %v\n", out, err)
		return exitFailure
	}
	return exitOK
}

// parseArgs reads the only flag, -out. help is true for -h, -help and --help; err names any
// other problem (unknown flag, missing value, extra argument).
func parseArgs(args []string) (out string, help bool, err error) {
	fs := flag.NewFlagSet("configschema", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.StringVar(&out, "out", defaultOut, "JSON file to write")
	err = fs.Parse(args)
	switch {
	case errors.Is(err, flag.ErrHelp):
		return "", true, nil
	case err != nil:
		return "", false, err
	case fs.NArg() > 0:
		return "", false, fmt.Errorf("unexpected argument %q", fs.Arg(0))
	}
	return out, false, nil
}

// writeUsage prints the usage text. A failing write to stdout or stderr leaves nothing to report
// it to, so its error is dropped on purpose.
func writeUsage(w io.Writer) {
	_, _ = fmt.Fprintf(w, "Usage: configschema [-out file]\n\n"+
		"Exports the configuration schema of the server as JSON.\n\n"+
		"Flags:\n  -out string\n    \tJSON file to write (default %q)\n", defaultOut)
}

// export returns the JSON document of keys, sorted by name; the order of keys does not matter,
// and keys itself is not changed. HTML characters stay as they are ("<" in a secret_ref default
// such as file:<secrets.dir>/x), so the file reads like the chapter table.
//
// The error comes from the JSON encoder; with string and bool fields it does not occur.
func export(keys []config.Key) ([]byte, error) {
	doc := schemaFile{Version: fileVersion, Keys: make([]fileKey, 0, len(keys))}
	for _, k := range keys {
		enum := slices.Clone(k.Enum)
		if enum == nil {
			enum = []string{}
		}
		doc.Keys = append(doc.Keys, fileKey{
			Name:     k.Name,
			Env:      config.EnvName(k.Name),
			Kind:     k.Kind.String(),
			Default:  k.Default,
			Required: k.Required,
			Enum:     enum,
			Min:      k.Min,
			Max:      k.Max,
			Chapter:  k.Chapter,
			Doc:      k.Doc,
		})
	}
	slices.SortFunc(doc.Keys, func(a, b fileKey) int { return strings.Compare(a.Name, b.Name) })

	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(doc); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// writeFile writes data to path with the usual permissions of a checked-in file (0666 before
// umask), unlike os.WriteFile with an explicit mode. The error joins a failed write and a failed
// close, so a full disk is never reported as success.
func writeFile(path string, data []byte) error {
	f, err := os.Create(filepath.Clean(path)) //nolint:gosec // G703: path is the -out argument of the developer running go generate; writing there is the purpose.
	if err != nil {
		return err
	}
	_, werr := f.Write(data)
	return errors.Join(werr, f.Close())
}
